import type { IncomingMessage, ServerResponse } from "node:http";
import { randomUUID } from "node:crypto";

interface Note {
  id: string;
  title: string;
  body: string;
}

class HttpError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

function send(res: ServerResponse, status: number, payload: unknown): void {
  const data = JSON.stringify(payload);
  res.writeHead(status, { "content-type": "application/json" });
  res.end(data);
}

async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of req) chunks.push(chunk as Buffer);
  return Buffer.concat(chunks).toString("utf8");
}

function parseJson(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    throw new HttpError(400, "Request body is not valid JSON");
  }
}

function validateNote(input: unknown): { title: string; body: string } {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    throw new HttpError(400, "Request body must be a JSON object");
  }
  const { title, body } = input as Record<string, unknown>;
  if (typeof title !== "string" || title.trim() === "") {
    throw new HttpError(400, "title must be a non-empty string");
  }
  if (body !== undefined && typeof body !== "string") {
    throw new HttpError(400, "body must be a string");
  }
  return { title, body: body ?? "" };
}

type Store = Map<string, Note>;

async function create(store: Store, req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields = validateNote(parseJson(await readBody(req)));
  const note: Note = { id: randomUUID(), ...fields };
  store.set(note.id, note);
  send(res, 201, note);
}

function get(store: Store, res: ServerResponse, id: string): void {
  const note = store.get(id);
  if (!note) throw new HttpError(404, "Note not found");
  send(res, 200, note);
}

async function route(store: Store, req: IncomingMessage, res: ServerResponse): Promise<void> {
  const path = new URL(req.url ?? "/", "http://localhost").pathname;
  const match = /^\/notes\/([^/]+)$/.exec(path);
  if (path === "/health" && req.method === "GET") return send(res, 200, { status: "ok" });
  if (path === "/notes" && req.method === "POST") return create(store, req, res);
  if (path === "/notes" && req.method === "GET") return send(res, 200, [...store.values()]);
  if (match && req.method === "GET") return get(store, res, decodeURIComponent(match[1]));
  throw new HttpError(404, "Not found");
}

function handleError(res: ServerResponse, err: unknown): void {
  if (err instanceof HttpError) return send(res, err.status, { error: err.message });
  send(res, 500, { error: "Internal server error" });
}

function logOnFinish(req: IncomingMessage, res: ServerResponse): void {
  const start = process.hrtime.bigint();
  const path = (req.url ?? "/").split("?")[0];
  res.on("finish", () => {
    const ms = Number(process.hrtime.bigint() - start) / 1e6;
    process.stdout.write(`${req.method} ${path} ${res.statusCode} ${ms.toFixed(1)}ms\n`);
  });
}

export function createServer(): http.Server {
  const store: Store = new Map();
  return http.createServer((req, res) => {
    logOnFinish(req, res);
    route(store, req, res).catch((err: unknown) => handleError(res, err));
  });
}
